(209, 5, '', 'Mejoramiento a ruta escénica - Ruta G-25, sector Las Vizcachas - San Gabriel', 19, '', 33, '', '', 'Consolidar la Ruta G-25 como ruta escénica del Cajón del Maipo, incorporando mejoras paisajísticas, miradores, señalización turística, áreas de descanso y tratamiento del borde de camino.', 'Si', 'Varias localidades', '14', '31', NULL, 3, 0, '', '', '', '0.00', '0.00', '1', 10, '', 0, 0, 'Sectorial ', '', '', '-33.602842', '-70.355287', '2026-03-17 19:41:07', '2026-04-15 13:53:03', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL),
(210, 5, '', 'Mejoramiento a ruta escénica - Ruta G-345 entre Ruta G-25 y control de acceso a Río Olivares (km 22)', 19, '', 34, '', '', 'Potenciar la Ruta G-345 como acceso escénico hacia el valle del Río Olivares, incorporando mejoras de infraestructura vial, miradores, señalización interpretativa y puntos de detención segura para visitantes.', 'Si', 'Entre El Manzano y acceso a parque', '14', '31', NULL, 3, 0, '', '', '', '0.00', '0.00', '1', 10, '', 0, 0, 'Sectorial ', '', '', '-33.547075', '-70.284589', '2026-03-17 19:41:07', '2026-04-15 13:53:32', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL),
(211, 4, 'no', 'Mejoramiento conectividad digital en el subterritorio', NULL, NULL, NULL, NULL, NULL, 'Las localidades de Las Vertientes, El Canelo, El Manzano, El Guayacán, El Toyo, El Melocotón, San Alfonso, El Ingenio, El Volcán, San Gabriel, Baños Morales y Lo Valdés poseen actualmente mala conectividad digital, por lo cual, es fundamental dotarlas de tecnología adecuada mediante un convenio de colaboración con SUBTEL. En este contexto se requiere el mejoramiento de cobertura y acceso a señal de telefonía celular e internet en la comuna dado que esta varía dependiendo del sector de la comuna en el que se encuentre. Esto afecta a diversas localidades y se traduce en baja conectividad en caso de incendios, temporales, uso de ambulancias, entre otras emergencias. Asimismo, permitiría mejorar la promoción de los productos de los emprendedores de la comuna y su comercialización a través de una mayor conectividad a plataformas de internet.', 'No', NULL, '1', '1', NULL, 3, 0, 'Alto', 'Bajo', NULL, '23600000.00', '278875000.00', '1', 10, NULL, NULL, NULL, 'FNDR - SECTORIAL', 'Municipio', '6273.3', NULL, NULL, '2026-03-17 19:41:07', '2026-04-12 17:06:15', NULL, 1, '0.00', '0.00', '0.00', NULL),
(212, 4, '', 'Construcción de Mercado San José de Maipo', 20, '', 35, '', '', 'Construcción de un mercado local para productos agrícolas, artesanales y gastronómicos.', 'Si', 'San José de Maipo', '14', '38', NULL, 3, 0, '', '', '', '320.00', '1.44', '1', 10, '', 0, 0, 'FNDR', 'MINAGRI', '', '-33.642985', '-70.356215', '2026-03-17 19:41:07', '2026-04-15 13:54:02', '22 - Super usuario', 1, '321.44', '0.00', '0.00', '1'),
(213, 4, 'no', 'Plan maestro de gestión de tránsito San José de Maipo ', NULL, NULL, NULL, NULL, NULL, 'El estudio incorpora la recopilación de información que permita identificar las problemáticas de movilidad, definir las características físicas, geométricas y operacionales definitivas de las áreas de proyecto, además de determinar los montos de inversión necesarios y su rentabilidad social. De esta manera, y una vez concluido el estudio, las autoridades locales y regionales contarán con una cartera de iniciativas de inversión en transporte y movilidad, a un nivel tal que puedan ser postuladas directamente a etapa de ejecución. Esta cartera estará compuesta por distintos tipos de proyectos, tales como: los que requieren de informes técnicos específicos, y por otros que requieren diseños sobre planimetría. Para este efecto se consideran los siguientes productos: Recopilación de Antecedentes, Desarrollo de Catastros y Monografías - Levantamiento de Información - Encuesta Origen Destino de Viajes en Hogares - Diagnóstico de Movilidad - Desarrollar una Imagen Objetivo de Transporte - Generar un Plan Maestro de Ciclorutas - Desarrollo de una Cartera de Proyectos de Movilidad.', 'No', NULL, '12', 'b', NULL, 4, 0, NULL, NULL, NULL, NULL, '200000000.00', NULL, NULL, NULL, NULL, NULL, 'FNDR', 'SECTRA - MTT', '19519', NULL, NULL, '2026-03-17 19:41:07', '2026-03-26 16:42:52', NULL, 1, '0.00', '0.00', '0.00', NULL),
(214, 4, 'no', 'Programa de asesoría para la gestión del riego y uso eficiente del recurso hídrico', NULL, NULL, NULL, NULL, NULL, 'Programa que comprende el traspaso de competencias en materia de gestión eficiente del agua, con énfasis en Ley de Riego, tecnologías sustentables y postulación a financiamiento de iniciativas de mejoramiento y construcción de obras de riego, considerando los siguientes aspectos: Gestión eficiente del recurso hídrico intrapredial - Transferencia de tecnologías de riego eficiente y racional - Capacitaciones en innovaciones tecnológicas en recursos hídricos - Marco Legal en materia de Riego - Fuentes de financiamiento para el mejoramiento de los sistemas de riego - Asistencia técnica para la postulación de proyectos a la Ley de Fomento al Riego y Drenaje (N°18.450)', 'No', NULL, '8', 'c', NULL, 2, 0, NULL, NULL, NULL, NULL, '630000000.00', NULL, NULL, NULL, NULL, NULL, 'FNDR', 'CNR', '1350', NULL, NULL, '2026-03-17 19:41:07', '2026-03-26 16:42:52', NULL, 1, '0.00', '0.00', '0.00', NULL);
INSERT INTO `proyectos_sep_2026` (`id`, `instrumento`, `preseleccionado`, `nombre`, `lineamiento_id`, `lineamiento`, `objetivo_id`, `objetivo`, `brecha`, `descripcion`, `plan_maestro`, `localizacion`, `sector`, `subsector`, `codigo_bip`, `tipo`, `unidad_responsable_id`, `impacto_territorial`, `foco_turismo`, `codigo_idi`, `p_diseno`, `p_ejecucion`, `etapa`, `proceso`, `informacion`, `finicio`, `ftermino`, `fuente`, `instituciones_vinculadas`, `beneficiarios`, `lat`, `lng`, `proyectos_created`, `proyectos_updated`, `proyectos_user`, `proyectos_status`, `total`, `avance_actividades`, `avance_financiero`, `geo_capa`) VALUES
(215, 4, 'no', 'Programa de regularización derechos de aprovechamiento de aguas', NULL, NULL, NULL, NULL, NULL, 'El programa considera la capacitación, asesoría, apoyo y seguimiento para la regularización y saneamiento de los derechos de aprovechamiento de aguas de los regantes identificados en las comunas de Alhué, San Pedro, Melipilla, María Pinto, San José de Maipo, Pirque, Paine, Isla de Maipo. Incluye capacitación y asesoría en aspectos legales, administrativos, técnicos, organizacionales y de gestión. Consiste en la inscripción de los derechos de aprovechamiento de agua, para lo cual se contemplan dos procedimientos según corresponda: constitución o regularización, siendo las actividades a realizar: inspección técnica a terreno verificando los requerimientos de cada peticionario a objeto de obtener los antecedentes técnicos y legales para la formulación de la solicitud de derecho de aprovechamiento de agua, posteriormente la solicitud se presenta al servicio respectivo para la tramitación de la misma hasta obtener la resolución de aprobación y otorgación del derecho, reducción a escritura pública e inscripción de la misma en el conservador de bienes raíces respectivo, obtención de certificado de dominio vigente del derecho de aprovechamiento inscrito y entrega a los beneficiados.', 'No', NULL, '8', 'c', NULL, 2, 0, NULL, NULL, NULL, NULL, '320000000.00', NULL, NULL, NULL, NULL, NULL, 'FNDR', 'DGA MOP', '1064.01', NULL, NULL, '2026-03-17 19:41:07', '2026-03-26 16:42:52', NULL, 1, '0.00', '0.00', '0.00', NULL),
(216, 4, 'no', 'Programa asesoría para la obtención de resoluciones sanitarias', NULL, NULL, NULL, NULL, NULL, 'El programa considera la capacitación y asesoría especializada para la obtención de resoluciones sanitarias en aquellos emprendimientos que lo requieran dentro de las comunas de San Pedro, Curacaví, San José de Maipo y Til Til. Incluye el apoyo y seguimiento a la gestión de las resoluciones ante los organismos técnicos correspondientes, así como instancias de capacitación para el fortalecimiento de las competencias de los micro y pequeños productores de las comunas priorizadas. Cabe indicar que la obtención de resoluciones sanitarias es fundamental para la competitividad de los emprendimientos, sobre todo de aquellos relacionados directamente con el desarrollo del turismo y la elaboración de productos agroartesanales (restaurantes, alojamiento, producción de mermeladas, manjar, frutas en conservas, entre otros productos agropecuarios procesados)', 'No', NULL, '14', 'c', NULL, 2, 0, NULL, NULL, NULL, NULL, '240000000.00', NULL, NULL, NULL, NULL, NULL, 'FNDR', 'MINAGRI', '1125.1500000000001', NULL, NULL, '2026-03-17 19:41:07', '2026-03-26 16:42:52', NULL, 1, '0.00', '0.00', '0.00', NULL),
(217, 4, 'no', 'Programa de fortalecimiento del agroturismo y turismo patrimonial', NULL, NULL, NULL, NULL, NULL, 'El programa busca fortalecer una oferta de experiencias innovadoras, con el objetivo de poner en valor el patrimonio cultural e inmaterial de las comunas, así como la ruralidad asociada a la producción agrícola y la cultura tradicional campesina. De esa manera, se busca promover los subterritorios priorizados como destinos emergentes, logrando atraer a los visitantes que deseen nuevas experiencias. Para este efecto se considera un apoyo en la conformación de destinos y oferta turística, incluyendo diseño de planes y programas, así como difusión de estos, incluyendo el traspaso de competencias para una gestión adecuada de los emprendimientos que rescaten la cultura y tradiciones locales. El programa busca promover el desarrollo turístico de las comunas foco de interés, mediante la difusión y el desarrollo de negocios turísticos. Para este efecto se consideran las siguientes actividades: Consolidación de la oferta turística local, mejoramiento de la calidad de atención turística, potenciar el desarrollo de productos turísticos, así como la difusión y promoción de servicios turísticos. La formulación del programa definirá en detalle los componentes y las actividades que involucraría esta iniciativas.', 'No', NULL, '14', 'c', NULL, 2, 0, NULL, NULL, NULL, NULL, '240000000.00', NULL, NULL, NULL, NULL, NULL, 'FNDR - SECTORIAL', 'SERNATUR', '37357', NULL, NULL, '2026-03-17 19:41:07', '2026-03-26 16:42:52', NULL, 1, '0.00', '0.00', '0.00', NULL),
