(398, 9, 'no', 'Difusión de contenido informativo en las redes sociales municipales.', 59, 'Adaptación', NULL, NULL, NULL, 'Aumentar la conciencia y el conocimiento de la comunidad de San José de Maipo sobre el cambio climático, la educación ambiental y los parámetros medioambientales relevantes para la comuna, a través de la difusión de contenido informativo en las redes sociales municipales.', 'No', NULL, '9', 'a', NULL, 4, 0, NULL, NULL, NULL, NULL, '3000.00', NULL, NULL, NULL, 2025, 2030, 'Municipal y Fondos Concursables', 'Comunidad Organizaciones públicas y privadas', NULL, NULL, NULL, '2026-03-17 19:41:07', '2026-03-26 16:42:52', NULL, 1, '0.00', '0.00', '0.00', NULL),
