(509, 13, '', 'Recuperación de puente ferroviario El Manzano', 20, '', 124, '', '', 'Recuperación de puente ferroviario El Manzano y ponerlo a disposición de la actividad cultural y turística.\r\n', 'Si', '', '4', '38', NULL, 3, 0, '', '', '', '0.00', '0.00', '', 0, '', 0, 0, '', '', '', '-33.582007', '-70.409202', '2026-04-14 15:20:33', '2026-04-15 14:03:06', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL),
(510, 13, '', 'Construcción de centro de distribución logística de reciclaje, comuna de San José de Maipo', 2, '', 0, '', '', 'La iniciativa contempla la construcción de un centro comunal de distribución y logística para reciclaje que permita consolidar la recepción, clasificación, almacenamiento transitorio y despacho de materiales valorizables. Debe articularse con puntos limpios, campañas de separación en origen, convenios con gestores autorizados y educación ambiental, fortaleciendo la capacidad operativa municipal frente a la presión turística y avanzando en estándares asociados a Ley REP, reducción de microbasurales y mejora de la imagen territorial.', 'Si', '', '9', '16', NULL, 3, 0, '', '', '', '0.00', '0.00', '', 0, '', 0, 0, '', '', '', '-33.643646', '-70.355710', '2026-04-14 15:22:22', '2026-04-15 14:03:37', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL),
(511, 0, '', 'Mejoramiento refugio Lagunillas', 0, '', 0, '', '', 'Proyecto orientado al mejoramiento del refugio existente en Lagunillas, considerando obras de rehabilitación, ampliación o modernización de sus espacios de alojamiento y apoyo. Puede incorporar mejoras en habitabilidad, eficiencia térmica, servicios higiénicos, seguridad, áreas comunes y equipamiento complementario, contribuyendo a consolidar una oferta de montaña de cuatro estaciones y a reforzar la red de infraestructura base para actividades deportivas, recreativas y educativas en altura.', 'Si', '', '', '', NULL, 0, 0, '', '', '', '0.00', '0.00', '', 0, '', 0, 0, '', '', '', '-33.608108', '-70.288580', '2026-04-14 15:22:47', '2026-04-15 14:04:07', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL),
(512, 13, '', 'Zona típica y museo de sitio El Volcán', 0, '', 0, '', '', 'Iniciativa destinada a proteger y activar el conjunto patrimonial de El Volcán mediante la delimitación y puesta en valor de un área de interés patrimonial y la habilitación de un museo de sitio. Puede considerar restauración o consolidación de vestigios, diseño museográfico e interpretativo, señalética, rutas patrimoniales, espacio público de apoyo y programación cultural, con el fin de rescatar la memoria de la actividad minera y del ferrocarril, fortalecer la identidad comunitaria y generar un nuevo nodo de turismo patrimonial en la alta cordillera.', 'Si', '', '', '', NULL, 0, 0, '', '', '', '0.00', '0.00', '', 0, '', 0, 0, '', '', '', '-33.815155', '-70.169085', '2026-04-14 15:23:13', '2026-04-15 14:04:41', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL),
(513, 13, '', 'Centro de interpretación del patrimonio ferroviario del Cajón del Maipo Estación El Melocotón.', 0, '', 0, '', '', 'Programa de recuperación de infraestructura ferroviaria histórica y patrimonio minero.', 'Si', '', '', '', NULL, 0, 0, '', '', '', '0.00', '0.00', '', 0, '', 0, 0, '', '', '', '-33.693268', '-70.335740', '2026-04-14 15:24:10', '2026-04-15 14:05:07', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL),
(514, 13, '', 'Centro de bienvenida, información y museo de la memora local ex estación La Obra', 0, '', 0, '', '', 'Programa de recuperación de infraestructura ferroviaria histórica y patrimonio minero.', 'Si', '', '', '', NULL, 0, 0, '', '', '', '0.00', '0.00', '', 0, '', 0, 0, '', '', '', '-33.592119', '-70.486767', '2026-04-14 15:25:15', '2026-04-15 14:06:00', '22 - Super usuario', 1, '0.00', '0.00', '0.00', NULL);
